const assert=require('node:assert/strict')
const fs=require('node:fs')
const path=require('node:path')
const ts=require('typescript')
const Module=require('node:module')
const root=process.cwd()
function imported(filepath){
 const full=path.join(root,filepath),source=fs.readFileSync(full,'utf8')
 const js=ts.transpileModule(source,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2020}}).outputText
 const mod=new Module(full,module);mod.filename=full;mod.paths=Module._nodeModulePaths(path.dirname(full));mod._compile(js,full)
 return mod.exports
}
const {refItemProducaoInstalacao,disponibilidadePeca,validarRegistroInstalacao}=imported('lib/vendaInstalacaoProducao.ts')
assert.equal(refItemProducaoInstalacao({id:'item-abc'},0),'item-abc')
assert.equal(refItemProducaoInstalacao({descricao:'Porta de giro'},0),'item-1')
const parcial=disponibilidadePeca([
 {item_ref:'porta-1',tipo_producao:'esquadria',status:'conferencia',bloqueada:false,quantidade:3,quantidade_produzida:2}
],'porta-1',3)
assert.equal(parcial.prontas,2)
assert.equal(parcial.faltantes,1)
assert.equal(parcial.estado,'parcial')
assert.equal(validarRegistroInstalacao({existente:0,novo:2,status:'em_instalacao',quantidadePlanejada:3,disponibilidade:parcial}),null)
assert.match(validarRegistroInstalacao({existente:2,novo:3,status:'pendencia',quantidadePlanejada:3,disponibilidade:parcial}),/Produção insuficiente/)
assert.equal(disponibilidadePeca([{item_ref:'p',tipo_producao:'esquadria',status:'concluida',bloqueada:false,quantidade:1}], 'p',1).prontas,1)
assert.equal(disponibilidadePeca([], 'porta-1',1).prontas,0)
// Iniciar instalação pode acontecer com zero unidade instalada, se há material pronto.
assert.equal(validarRegistroInstalacao({existente:0,novo:0,status:'em_instalacao',quantidadePlanejada:3,disponibilidade:parcial}),null)
assert.match(validarRegistroInstalacao({existente:0,novo:0,status:'em_instalacao',quantidadePlanejada:3,disponibilidade:disponibilidadePeca([], 'porta-1',3)}),/produzidas disponíveis/)

const fluxo=imported('lib/vendaFluxoResumo.ts')
const base={valorVenda:2400,contas:[],compras:[],ordens:[],instalacoes:[]}
let obj={...base,instalacoes:[{item_ref:'porta-1',quantidade:1,quantidade_instalada:1,status:'pendencia',pendencia:'Falta cantoneira',checklist:{nivelamento:true,vedacao:true,acabamento:false,limpeza:true}}]}
const a=fluxo.avaliarFluxoVenda(obj)
assert.equal(a.quantidadeInstalada,1)
assert.equal(a.quantidadeFinalizada,0)
assert.equal(a.progressoInstalacao,0)
assert.equal(a.podeEncerrar,false)
obj={...obj,instalacoes:[{item_ref:'porta-1',quantidade:1,quantidade_instalada:1,status:'instalado',pendencia:null,checklist:{nivelamento:true,vedacao:true,acabamento:true,limpeza:true}}]}
const b=fluxo.avaliarFluxoVenda(obj)
assert.equal(b.quantidadeFinalizada,1)
assert.equal(b.progressoInstalacao,100)
assert.equal(b.podeEncerrar,false) // Financeiro e Produção ainda pendentes.
